import { existsSync, mkdirSync } from "node:fs";
import { dirname } from "node:path";
import Database from "better-sqlite3";

// Server-only module. Must never be imported from client-executed code
// (only from routeLoader$ / routeAction$ closures).

const DB_PATH = "data/inventory.db";

let dbInstance: Database.Database | null = null;

export function getDb(): Database.Database {
  if (dbInstance) {
    return dbInstance;
  }

  const dir = dirname(DB_PATH);
  if (!existsSync(dir)) {
    mkdirSync(dir, { recursive: true });
  }

  const db = new Database(DB_PATH);
  db.pragma("journal_mode = WAL");
  db.pragma("foreign_keys = ON");
  dbInstance = db;
  return db;
}

export interface ProductWithQuantity {
  id: number;
  sku: string;
  name: string;
  quantity: number;
}

export function listProductsWithQuantity(): ProductWithQuantity[] {
  const db = getDb();
  const rows = db
    .prepare(
      `SELECT
         p.id AS id,
         p.sku AS sku,
         p.name AS name,
         COALESCE(SUM(m.delta), 0) AS quantity
       FROM products p
       LEFT JOIN stock_movements m ON m.product_id = p.id
       GROUP BY p.id, p.sku, p.name
       ORDER BY p.id ASC`,
    )
    .all() as ProductWithQuantity[];
  return rows;
}

export type MovementType = "receive" | "ship";

export type MovementResult =
  | { ok: true }
  | { ok: false; error: string };

/**
 * Atomically applies a stock movement:
 *  - receive: inserts a ledger row with delta = +quantity
 *  - ship: inserts a ledger row with delta = -quantity, only if current
 *          on-hand quantity (sum of ledger deltas) is >= quantity
 *
 * The existence check, on-hand computation, and insert all happen inside
 * a single better-sqlite3 transaction so concurrent ship requests can
 * never oversell a product.
 */
export function applyMovement(
  productId: number,
  type: MovementType,
  quantity: number,
): MovementResult {
  const db = getDb();

  const run = db.transaction((): MovementResult => {
    const product = db
      .prepare("SELECT id FROM products WHERE id = ?")
      .get(productId) as { id: number } | undefined;

    if (!product) {
      return { ok: false, error: `Product ${productId} does not exist.` };
    }

    if (type === "receive") {
      db.prepare(
        "INSERT INTO stock_movements (product_id, delta, reason) VALUES (?, ?, ?)",
      ).run(productId, quantity, "receive");
      return { ok: true };
    }

    // type === "ship"
    const row = db
      .prepare(
        "SELECT COALESCE(SUM(delta), 0) AS onHand FROM stock_movements WHERE product_id = ?",
      )
      .get(productId) as { onHand: number };

    if (row.onHand < quantity) {
      return {
        ok: false,
        error: `Insufficient stock: only ${row.onHand} unit(s) available.`,
      };
    }

    db.prepare(
      "INSERT INTO stock_movements (product_id, delta, reason) VALUES (?, ?, ?)",
    ).run(productId, -quantity, "ship");
    return { ok: true };
  });

  // better-sqlite3 transactions are synchronous and use BEGIN IMMEDIATE-like
  // exclusivity via its default transaction mode, ensuring the read-then-write
  // here is atomic with respect to other connections/calls.
  return run.immediate();
}

import { component$ } from "@builder.io/qwik";
import {
  Form,
  routeAction$,
  routeLoader$,
  z,
  zod$,
} from "@builder.io/qwik-city";
import type { DocumentHead } from "@builder.io/qwik-city";

export const useProducts = routeLoader$(async () => {
  // Import kept inside the loader closure so the sqlite module never
  // ends up in the client bundle.
  const { listProductsWithQuantity } = await import("~/lib/db");
  return listProductsWithQuantity();
});

export const useMovementAction = routeAction$(
  async (data, { fail }) => {
    const { applyMovement } = await import("~/lib/db");

    const result = applyMovement(data.productId, data.type, data.quantity);

    if (!result.ok) {
      return fail(400, { message: result.error });
    }

    return { success: true as const };
  },
  zod$({
    productId: z.coerce
      .number({ invalid_type_error: "Product is required." })
      .int("Product id must be an integer.")
      .positive("Product id must be positive."),
    type: z.enum(["receive", "ship"], {
      errorMap: () => ({ message: "Type must be either receive or ship." }),
    }),
    quantity: z.coerce
      .number({ invalid_type_error: "Quantity must be a number." })
      .int("Quantity must be an integer.")
      .positive("Quantity must be a positive integer."),
  }),
);

export default component$(() => {
  const products = useProducts();
  const action = useMovementAction();

  return (
    <>
      <h1>Inventory Stock Manager</h1>

      <table>
        <thead>
          <tr>
            <th>SKU</th>
            <th>Name</th>
            <th>On hand</th>
          </tr>
        </thead>
        <tbody>
          {products.value.map((p) => (
            <tr key={p.id} data-testid={`product-${p.id}`}>
              <td>{p.sku}</td>
              <td>{p.name}</td>
              <td data-testid={`qty-${p.id}`}>{p.quantity}</td>
            </tr>
          ))}
        </tbody>
      </table>

      <Form action={action} data-testid="movement-form">
        <label>
          Product
          <select name="productId">
            {products.value.map((p) => (
              <option key={p.id} value={p.id}>
                {p.sku} - {p.name}
              </option>
            ))}
          </select>
        </label>

        <label>
          Type
          <select name="type">
            <option value="receive">Receive</option>
            <option value="ship">Ship</option>
          </select>
        </label>

        <label>
          Quantity
          <input type="number" name="quantity" min="1" step="1" />
        </label>

        <button type="submit">Submit</button>
      </Form>

      {action.value?.failed && (
        <div data-testid="error">
          {(action.value as { message?: string }).message ??
            "Submission failed."}
        </div>
      )}
    </>
  );
});

export const head: DocumentHead = {
  title: "Inventory Stock Manager",
  meta: [
    {
      name: "description",
      content: "Server-authoritative inventory stock management",
    },
  ],
};

